#!/usr/bin/env bash
export GIT_AUTHOR_NAME=Dev GIT_AUTHOR_EMAIL=dev@example.com GIT_COMMITTER_NAME=Dev GIT_COMMITTER_EMAIL=dev@example.com
o="$(git rev-parse --show-toplevel)/.git/test-origin"
case "$1 $2" in
  "pr view") printf '{"number":7,"title":"Show empty results","state":"OPEN","isDraft":false,"headRefName":"empty-results","headRefOid":"%s","baseRefName":"main"}' "$(git -C "$o" rev-parse empty-results)" ;;
  "repo view") echo '{"mergeCommitAllowed":false,"squashMergeAllowed":true,"rebaseMergeAllowed":false}' ;;
  "pr list") echo '[{"number":8,"headRefName":"results-filters"}]' ;;
  "pr merge") git -C "$o" merge -q --squash empty-results && git -C "$o" commit -qm 'Show empty results (#7)' ;;
  *) echo "fake gh: unexpected $*" >&2; exit 1 ;;
esac
